/* Shared link behaviour for every theme (loaded by the theme-switcher block that switcher.py injects).
 * Theme pages use placeholder links (href="#"). Every menu, footer and card label maps to a real page of the same
 * theme (generated by _build/build.mjs), so on load each link gets its real address: hover shows it, a new tab works.
 * A few labels belong to home-page sections (How it works, the assessment card); those scroll on the home page and
 * open the home page at that section from every other page. */
(function () {
  var m = location.pathname.match(/^\/(concept-[^/]+)\//);
  if (!m) return;
  var ROOT = m[0];
  var IS_HOME = location.pathname === ROOT || location.pathname === ROOT + 'index.html';
  // Placeholder contact number (+91 90000 00000) may belong to a real person: never dial or message it.
  var DEMO_NUMBER = /919000000000/;
  // home section key -> phrase that only that section contains (heading text from CONTENT.md)
  var SECTIONS = {
    specialties: 'Eight specialties, chosen for depth',
    costs: 'The same operation, at a fraction of the price',
    destinations: 'Seven cities, one standard of care',
    trust: 'Every partner hospital holds Joint Commission International',
    how: 'Five stops. One coordinator. Door to door',
    support: 'One person who knows your case, day and night',
    story: 'An illustrative patient journey',
    partners: 'Grow with a network built on transparency',
    final: 'Begin with a free AI assessment'
  };
  var CITIES = { 'delhi ncr': 'delhi-ncr', chennai: 'chennai', mumbai: 'mumbai', bengaluru: 'bengaluru', hyderabad: 'hyderabad',
    vijayawada: 'vijayawada', visakhapatnam: 'visakhapatnam' };
  // label -> page (relative to the theme root), "#key" for a home section, "assess" for the assessment card
  var ROUTES = {
    'heal india global': '', 'home': '',
    'start an assessment': 'assess', 'get started': 'assess', 'free ai assessment': 'assess', 'get a free ai assessment': 'assess',
    'not sure which treatment you need?': 'assess',
    'how it works': '#how', 'see the whole journey': '#how', 'see every stop': '#how',
    // Treatments
    'treatments': 'treatments/', 'all treatments': 'treatments/', 'browse all treatments': 'treatments/',
    'heart bypass (cabg)': 'treatments/cardiac-sciences/cabg/', 'knee replacement': 'treatments/orthopaedics/total-knee-replacement/',
    'hip replacement': 'treatments/orthopaedics/total-hip-replacement/', 'spine surgery': 'treatments/spine-surgery/',
    'weight-loss surgery': 'treatments/weight-loss-surgery/', 'cancer care': 'treatments/oncology/', 'oncology': 'treatments/oncology/',
    'organ transplant': 'treatments/organ-transplant/', 'neurosciences': 'treatments/neurosciences/', 'fertility and ivf': 'treatments/fertility-ivf/',
    'eye care': 'treatments/eye-care/', 'cardiac sciences': 'treatments/cardiac-sciences/', 'orthopaedics': 'treatments/orthopaedics/',
    'second opinion': 'second-opinion/', 'indicative costs': 'costs/', 'how quotes work': 'how-quotes-work/',
    'what a quote includes': 'how-quotes-work/#what-a-quote-includes',
    // Hospitals and destinations
    'all hospitals': 'hospitals/', 'accredited partner hospitals': 'hospitals/', 'jci and nabh explained': 'accreditation/',
    'how we verify': 'how-we-verify/', 'how we verify hospitals': 'how-we-verify/', 'compare hospitals': 'hospitals/compare/',
    'international desks': 'international-desks/', 'all seven cities': 'cities/', 'destinations': 'cities/', 'cities': 'cities/',
    // Doctors
    'doctors': 'doctors/', 'all doctors': 'doctors/', 'cardiac surgeons': 'doctors/cardiac-surgeons/', 'orthopaedic surgeons': 'doctors/orthopaedic-surgeons/',
    'oncologists': 'doctors/oncologists/', 'transplant surgeons': 'doctors/transplant-surgeons/', 'neurosurgeons': 'doctors/neurosurgeons/',
    'fertility specialists': 'doctors/fertility-specialists/', 'video consultation': 'video-consultation/', 'book a consultation': 'video-consultation/',
    'speak to a specialist from home': 'video-consultation/', 'find a doctor by name': 'doctors/#find', 'how we vet doctors': 'how-we-vet-doctors/',
    // Plan your trip
    'trip planning guide': 'plan-your-trip/', 'plan your trip': 'plan-your-trip/', 'travel and stay': 'plan-your-trip/',
    'e-medical visa': 'plan-your-trip/e-medical-visa/', 'e-medical visa decision': 'plan-your-trip/e-medical-visa/',
    'flights and airport pickup': 'plan-your-trip/flights-and-airport-pickup/', 'costs and payment': 'plan-your-trip/costs-and-payment/',
    'what to bring': 'plan-your-trip/what-to-bring/', 'where you will stay': 'plan-your-trip/where-you-will-stay/',
    'your coordinator': 'plan-your-trip/your-coordinator/', 'translators': 'plan-your-trip/translators/',
    'whatsapp and sos line': 'plan-your-trip/whatsapp-and-sos-line/',
    'in-country support': 'support/', 'patient support': 'support/', 'talk to a coordinator': 'support/',
    // Partners
    'partners': 'partners/', 'partner programme': 'partners/', 'become a partner': 'partners/hospitals/', 'become a partner hospital': 'partners/hospitals/',
    'hospitals': 'partners/hospitals/', 'requirements': 'partners/hospitals/requirements/', 'how referrals work': 'partners/how-referrals-work/',
    'join as an agent': 'partners/agents/', 'agents and facilitators': 'partners/agents/', 'commission and payouts': 'partners/agents/commission-and-payouts/',
    'marketing resources': 'partners/agents/marketing-resources/', 'talk to our partnerships team': 'partners/contact/', 'partnerships team': 'partners/contact/',
    'screened referrals, complete reports': 'partners/contact/',
    // Sign in and company
    'log in': 'login/', 'partner log in': 'login/#hospital', 'hospital log in': 'login/#hospital', 'agent log in': 'login/#agent',
    'about us': 'about/', 'contact': 'contact/', 'faqs': 'faq/', 'careers': 'careers/', 'privacy': 'privacy/', 'terms': 'terms/',
    'cookies': 'cookies/', 'accessibility': 'accessibility/'
  };
  Object.keys(CITIES).forEach(function (c) { ROUTES[c] = 'cities/' + CITIES[c] + '/'; });

  var norm = function (s) {
    return (s || '').replace(/[→↗]/g, '').replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim().toLowerCase();
  };
  // Cards and feature tiles wrap several lines in one link: match the start ("02 Orthopaedics Knee, hip…"), then a
  // distinctive phrase anywhere ("14 accredited partner hospitals…"), longest labels first.
  var all = Object.keys(ROUTES).sort(function (a, b) { return b.length - a.length; });
  var phrases = all.filter(function (l) { return l.length > 12; });
  function resolve(a) {
    var label = norm(a.getAttribute('aria-label') || a.textContent);
    if (label in ROUTES) return ROUTES[label];
    var bare = label.replace(/^[\d~]+\s*h?\s*/, '');
    for (var j = 0; j < all.length; j++) if (bare.indexOf(all[j]) === 0) return ROUTES[all[j]];
    for (var i = 0; i < phrases.length; i++) if (label.indexOf(phrases[i]) >= 0) return ROUTES[phrases[i]];
    return null;
  }
  function urlFor(route) {
    if (route === 'assess') return IS_HOME ? null : ROOT + 'assessment/';
    if (route.charAt(0) === '#') return IS_HOME ? null : ROOT + route;
    return ROOT + route;
  }

  function sectionFor(key) {
    var phrase = norm(SECTIONS[key]);
    var skip = function (n) {
      return /^(SCRIPT|STYLE|TEMPLATE|NOSCRIPT|HEADER|NAV|FOOTER)$/i.test(n.tagName) ||
        n.closest('header, nav, footer, .mega, [role="dialog"], [data-ts], #drawer, .drawer');
    };
    var has = function (n) { return !skip(n) && norm(n.textContent).indexOf(phrase) >= 0; };
    // first occurrence in document order, then down to the innermost element that still holds the phrase
    var nodes = document.body.querySelectorAll('*'), hit = null;
    for (var i = 0; i < nodes.length && !hit; i++) if (has(nodes[i])) hit = nodes[i];
    for (var deeper = hit; deeper; ) {
      hit = deeper; deeper = null;
      for (var c = 0; c < hit.children.length; c++) if (has(hit.children[c])) { deeper = hit.children[c]; break; }
    }
    if (!hit) return null;
    var sec = hit.closest('section');
    return sec && hit.getBoundingClientRect().top - sec.getBoundingClientRect().top < 400 ? sec : hit;
  }
  function headerOffset() {
    var hs = document.querySelectorAll('.site-header, body > header, header');
    for (var i = 0; i < hs.length; i++) {
      var cs = getComputedStyle(hs[i]);
      // the header's height where it sticks (the utility bar above it has scrolled away by then)
      if (cs.position === 'sticky' || cs.position === 'fixed') return hs[i].getBoundingClientRect().height + (parseFloat(cs.top) || 0);
    }
    return 0;
  }
  function scrollToEl(el, instant) {
    var gap = el.tagName === 'SECTION' ? 8 : 64; // a bare heading gets room for its eyebrow
    var y = el.getBoundingClientRect().top + scrollY - headerOffset() - gap;
    scrollTo({ top: Math.max(0, y), behavior: instant || matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
  }
  function toast(msg) {
    var t = document.getElementById('nl-toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'nl-toast'; t.setAttribute('role', 'status');
      t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:2147483001;background:#102A43;color:#fff;font:500 14px/1.4 Inter,system-ui,sans-serif;padding:12px 18px;border-radius:999px;box-shadow:0 12px 32px -12px rgba(16,42,67,.5);transition:opacity .2s;max-width:calc(100vw - 32px);text-align:center';
      document.body.appendChild(t);
    }
    t.textContent = msg; t.style.opacity = '1';
    clearTimeout(t._h); t._h = setTimeout(function () { t.style.opacity = '0'; }, 2600);
  }
  function closeMenus() {
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
  }
  function goHomeSection(route) {
    if (route === '') return scrollTo({ top: 0, behavior: 'smooth' });
    if (route === 'assess') {
      var input = document.querySelector('form#assess input, input[placeholder*="knee replacement" i]');
      if (input) {
        scrollToEl(input.closest('form') || input);
        // focus once the smooth scroll has settled (menus may hand focus back to their button while closing)
        setTimeout(function () { input.focus({ preventScroll: true }); }, 800);
        return;
      }
      return void (location.href = ROOT + 'assessment/');
    }
    var el = sectionFor(route.slice(1));
    if (el) scrollToEl(el);
  }

  /* Give every placeholder link its real address. */
  function decorate() {
    document.querySelectorAll('a[href]').forEach(function (a) {
      if (a.closest('[data-ts]')) return;
      var href = a.getAttribute('href');
      if (href !== '' && href.charAt(0) !== '#') return; // real URLs (pages, dvsoft.in, mailto:, ...) stay as they are
      var label = norm(a.getAttribute('aria-label') || a.textContent);
      if (/^whatsapp( us)?$/.test(label)) return a.setAttribute('href', 'https://wa.me/919000000000'); // demo number: click shows a note
      if (/^call( us)?$/.test(label)) return a.setAttribute('href', 'tel:+919000000000');
      var route = resolve(a);
      if (route === null) {
        // in-page anchors such as #stop-3 belong to the home page
        if (!IS_HOME && href.length > 1) a.setAttribute('href', ROOT + href);
        return;
      }
      if (route === '' && IS_HOME) return; // the logo scrolls to the top on the home page
      var url = urlFor(route);
      if (url) return a.setAttribute('href', url);
      // home page: point at the real form or section so the address is meaningful (the click still scrolls smoothly)
      var target = route === 'assess' ? document.getElementById('assess') : sectionFor(route.slice(1));
      if (target && target.id && (href === '#' || href === '')) a.setAttribute('href', '#' + target.id);
    });
  }
  decorate();
  addEventListener('load', decorate); // menus some themes build late

  // Opened from another page at a home section (/concept-x/#how): scroll there once the layout has settled.
  if (IS_HOME && location.hash.length > 1 && SECTIONS[location.hash.slice(1)] && !document.getElementById(location.hash.slice(1))) {
    addEventListener('load', function () {
      var el = sectionFor(location.hash.slice(1)), moved = false;
      if (!el) return;
      // photos above the section keep loading on slow connections and push it down: re-align until the visitor scrolls
      ['wheel', 'touchstart', 'keydown'].forEach(function (ev) { addEventListener(ev, function () { moved = true; }, { once: true, passive: true }); });
      [50, 600, 1500, 3000].forEach(function (ms) { setTimeout(function () { if (!moved) scrollToEl(el, true); }, ms); });
    });
  }

  /* "Start assessment" (form#assess in every theme) opens the assessment page with the treatment filled in. */
  document.addEventListener('submit', function (e) {
    var form = e.target;
    if (!form || form.id !== 'assess') return;
    e.preventDefault();
    e.stopImmediatePropagation(); // the theme's own placeholder handler must not run
    var input = form.querySelector('input');
    var need = input ? input.value.trim() : '';
    if (!need && input) { input.focus(); return toast('Type a treatment, or pick one of the popular options.'); }
    location.href = ROOT + 'assessment/?need=' + encodeURIComponent(need);
  }, true);

  function cityOf(text) {
    var t = norm(text);
    for (var c in CITIES) if (t.indexOf(c) === 0) return CITIES[c];
    return null;
  }

  document.addEventListener('click', function (e) {
    if (!e.target.closest || e.target.closest('[data-ts]')) return;
    // Destination atlas: a city button, or the big photo of the selected city, opens that city's page.
    var dest = IS_HOME && sectionFor('destinations');
    var cityBtn = dest && e.target.closest('button');
    if (cityBtn && dest.contains(cityBtn) && cityOf(cityBtn.textContent)) {
      location.href = ROOT + 'cities/' + cityOf(cityBtn.textContent) + '/';
      return;
    }
    var frame = dest && e.target.closest('#frame');
    if (frame) {
      var nameEl = document.getElementById('frame-name');
      if (nameEl && cityOf(nameEl.textContent)) { location.href = ROOT + 'cities/' + cityOf(nameEl.textContent) + '/'; return; }
    }
    var a = e.target.closest('a[href]');
    if (!a) return;
    var href = a.getAttribute('href');
    if (DEMO_NUMBER.test(href)) {
      e.preventDefault();
      return toast('Demo number. The real WhatsApp and phone numbers will be added before launch.');
    }
    if (href !== '' && href.charAt(0) !== '#') return; // real addresses navigate normally
    // Contact buttons without a real link yet: same note as the demo number.
    if (/^(whatsapp( us)?|call( us)?|\+91 90000 00000)$/.test(norm(a.getAttribute('aria-label') || a.textContent))) {
      e.preventDefault();
      return toast('Demo number. The real WhatsApp and phone numbers will be added before launch.');
    }
    var route = resolve(a);
    if (route === null) {
      if (href.length > 1 && document.getElementById(href.slice(1))) { setTimeout(closeMenus, 0); return; }
      e.preventDefault(); closeMenus(); return;
    }
    var url = urlFor(route);
    if (url) { e.preventDefault(); location.href = url; return; }
    e.preventDefault();
    closeMenus();
    requestAnimationFrame(function () { requestAnimationFrame(function () { goHomeSection(route); }); });
  }, true);

  // Home page: city buttons say where they lead.
  if (IS_HOME) addEventListener('load', function () {
    var dest = sectionFor('destinations');
    if (!dest) return;
    dest.querySelectorAll('button').forEach(function (b) {
      if (cityOf(b.textContent)) b.title = 'See partner hospitals and the city guide';
    });
    var frame = document.getElementById('frame');
    if (frame) { frame.style.cursor = 'pointer'; frame.title = 'See partner hospitals and the city guide'; }
  });

  window.__navLinks = { resolve: resolve, sectionFor: sectionFor, root: ROOT };
})();
